declare(strict_types=1);require dirname(__DIR__).'/src/bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");$manifest=(string)env('IMAGE_MANIFEST_URL','');if($manifest===''){echo "IMAGE_MANIFEST_URL não configurada. Nada alterado.\n";exit(0);} $raw=@file_get_contents($manifest);$items=json_decode((string)$raw,true);if(!is_array($items))throw new RuntimeException('Manifesto de imagens inválido');$base=rtrim((string)env('IMAGE_BASE_URL','https://img.farmacia.superamplitude.com'),'/');$st=$db->prepare('UPDATE medications SET image_url=?,updated_at=CURRENT_TIMESTAMP WHERE registration=?');$n=0;foreach($items as $i){$reg=trim((string)($i['registration']??''));$path=trim((string)($i['path']??''));if($reg===''||$path==='')continue;$url=preg_match('#^https?://#',$path)?$path:$base.'/'.ltrim($path,'/');$st->execute([$url,$reg]);$n+=$st->rowCount();}echo "IMAGES_OK updated=$n base=$base\n";
